        if h_idx > 0:
            region_h_start = h_lines[h_idx - 1] + 1
        else:
            region_h_start = 0

        if h_idx < len(h_lines):
            region_h_end = h_lines[h_idx] - 1
        else:
            region_h_end = rows - 1

        for v_idx in range(len(v_lines) + 1):
            if v_idx > 0:
                region_v_start = v_lines[v_idx - 1] + 1
            else:
                region_v_start = 0

